#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  # q holds the quote: bash 3.2 (macOS) keeps the backslash of a \' replacement.
  local line value sq="'\\''" q="'"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/$q}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# duckbill MCP setup: lets Claude Code, claude.ai and Grok Bot read duckbill
# through /mcp, signing in with Clerk over OAuth. It checks Railway serves the
# MCP endpoint, walks through registering it in Clerk, checks each hop with
# curl, then connects each client. Run it from the repo root once the MCP PR
# has merged: deploy/mcp-setup.sh. Safe to re-run: every check is repeated.
# It reads and writes only DUCKBILL_RAILWAY_DOMAIN in .env, and needs no secrets.

run_wizard() {

TOTAL_STAGES=8

cd "$(dirname "${BASH_SOURCE[0]}")/.."

# ── Helpers for this wizard ───────────────────────────────────────────────
ok()  { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
die() { printf '\n'; warn "$1"; printf '\n'; exit 1; }
# copy VALUE puts a value on the clipboard, if there's a clipboard tool.
copy() {
  if command -v wl-copy >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v xclip >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1; fi
}
# status URL [method]: the HTTP status code, or 000 when nothing answers.
status() { curl -sS -o /dev/null -w '%{http_code}' --max-time 10 -X "${2:-GET}" "$1" 2>/dev/null || true; }
# metadata: /mcp's protected resource metadata (JSON), or nothing.
metadata() { curl -fsS --max-time 10 "$API/.well-known/oauth-protected-resource/mcp" 2>/dev/null || true; }
# mcp_live: the metadata names this endpoint, so Railway runs the MCP change with Clerk set up.
mcp_live() { [[ "$(metadata | jq -r '.resource // empty' 2>/dev/null)" == "$MCP_URL" ]]; }
# challenge: the WWW-Authenticate header /mcp sends a request without a token.
challenge() {
  curl -sS -o /dev/null -D - --max-time 10 -X POST "$MCP_URL" 2>/dev/null \
    | tr -d '\r' | sed -n 's/^[Ww][Ww][Ww]-[Aa]uthenticate: //p'
}
# clerk_ready: Clerk's metadata advertises PKCE (S256) and client ID metadata documents (public
# clients). Whether Clerk then admits a given client shows in each client's end-to-end check.
clerk_ready() {
  curl -fsS --max-time 10 "$ISSUER/.well-known/oauth-authorization-server" 2>/dev/null | jq -e '
    (.code_challenge_methods_supported | index("S256")) and .client_id_metadata_document_supported == true
  ' >/dev/null 2>&1
}
# wait_for CHECK "what": retries CHECK every 10s for 5 minutes. Fails if it never passes.
wait_for() {
  printf '  Waiting for %s' "$2"
  for _ in $(seq 1 30); do "$1" && { printf '\n'; return 0; }; printf '.'; sleep 10; done
  printf '\n'; return 1
}
# tools_check "where": the end-to-end check, recorded if it didn't pass.
tools_check() {
  say "In $1, with duckbill turned on, ask:"
  printf '\n      %sUse duckbill to show my balances, then tell me how many tools duckbill has.%s\n\n' "$BOLD" "$RESET"
  say "It should give your account and pot balances and count 11 tools."
  if confirm "Did $1 answer from duckbill?"; then ok "$1 works"
  else
    SKIPPED+=("$1: duckbill didn't answer. Re-run this wizard: it repeats every check.")
    warn "If it said \"Not allowed\", it signed in as someone other than you: sign in with the"
    say  "  Google account you use for the dashboard. Otherwise re-run this wizard to repeat"
    say  "  the checks; if they all pass, remove the connector and add it again."
  fi
}

for tool in curl jq; do command -v "$tool" >/dev/null 2>&1 || die "Install $tool first."; done

banner "duckbill MCP setup"

# ── 1. duckbill's address ─────────────────────────────────────────────────
stage "duckbill's address"
say "Agents reach duckbill at https://<your Railway domain>/mcp."
note "deploy/setup.sh saved the domain; Railway shows it under duckbill → Settings → Networking."
while :; do
  ask DUCKBILL_RAILWAY_DOMAIN "duckbill's Railway domain (xxx.up.railway.app):" || die "No domain given."
  DUCKBILL_RAILWAY_DOMAIN=${DUCKBILL_RAILWAY_DOMAIN#https://}
  DUCKBILL_RAILWAY_DOMAIN=${DUCKBILL_RAILWAY_DOMAIN%%/*}
  [[ "$(status "https://$DUCKBILL_RAILWAY_DOMAIN/healthz")" == 200 ]] && break
  warn "Nothing answers at https://$DUCKBILL_RAILWAY_DOMAIN/healthz. Check the domain, or Railway."
done
write_env DUCKBILL_RAILWAY_DOMAIN "$DUCKBILL_RAILWAY_DOMAIN"
API="https://$DUCKBILL_RAILWAY_DOMAIN"
MCP_URL="$API/mcp"
ok "duckbill answers at $API"
printf '\n'; pause

# ── 2. Railway runs the MCP change ────────────────────────────────────────
stage "Railway: the MCP endpoint is deployed"
say "Checks Railway runs the version with /mcp. Merging the MCP PR deploys it once"
say "CI passes; nothing else changes on Railway (no new variables)."
if mcp_live; then
  ok "The metadata names $MCP_URL"
else
  say "Not yet: merge the MCP PR, then wait here while Railway deploys it."
  open_url "https://github.com/benjamingriff/duckbill/pulls"
  if wait_for mcp_live "the deploy"; then ok "The metadata names $MCP_URL"
  else
    warn "The metadata says: $(metadata || echo 'nothing')"
    note "\"OAuth is not configured\" means Railway's CLERK_PUBLISHABLE_KEY doesn't name a Clerk host."
    die "Check the PR merged and Railway's Deployments tab, then re-run."
  fi
fi
ISSUER=$(metadata | jq -r '.authorization_servers[0] // empty' 2>/dev/null || true)
[[ "$ISSUER" == https://* ]] || die "The metadata names no Clerk sign-in server. Re-run in a minute."
ok "Clerk signs agents in: $ISSUER"
printf '\n'; pause

# ── 3. Clerk: register the MCP server ─────────────────────────────────────
stage "Clerk: register the MCP server"
say "Tells Clerk about duckbill's MCP server, so it issues tokens for that URL and"
say "lets clients such as Claude register themselves (public clients)."
open_url "https://dashboard.clerk.com/~/agents/mcp-servers"
step "Check the top bar says the duckbill app and Development."
step "MCP servers should list exactly this URL. If not: Add MCP server (or Get started),"
say  "  MCP URL:"
note "      $MCP_URL"
copy "$MCP_URL" && note "      (on your clipboard)"
say  "  then Add server."
step "Turn on Allow public clients to connect for it."
printf '\n'; pause "Press Enter once it's listed with public clients on."
if wait_for clerk_ready "Clerk to advertise public clients"; then
  ok "Clerk advertises PKCE (S256) and client ID metadata documents (public clients)"
else
  warn "Clerk's metadata doesn't list client_id_metadata_document_supported yet."
  step "Configure → OAuth applications → Settings → Client onboarding: turn on Publish CIMD support."
  open_url "https://dashboard.clerk.com/~/oauth-applications"
  pause "Press Enter once it's on."
  if wait_for clerk_ready "Clerk to advertise public clients"; then ok "Clerk advertises public clients"
  else SKIPPED+=("Clerk: public clients (CIMD) for $MCP_URL"); fi
fi
printf '\n'; pause

# ── 4. Clerk: Include Audience ────────────────────────────────────────────
stage "Clerk: tokens name their audience"
say "duckbill only accepts a token issued for $MCP_URL, which it reads from the"
say "token's audience. Without one, every token is refused."
open_url "https://dashboard.clerk.com/~/oauth-applications"
step "Configure → OAuth applications → Settings: check Include Audience is on."
note "Clerk turns it on with the first MCP server, but nothing outside the dashboard shows it."
if ! confirm "Is Include Audience on?"; then
  SKIPPED+=("Clerk: turn on Include Audience (OAuth applications → Settings)")
  warn "Turn it on before connecting a client, or its token will be refused."
fi
printf '\n'; pause

# ── 5. Check each hop ─────────────────────────────────────────────────────
stage "Check each hop"
say "The three requests a client makes before you sign in:"
printf '\n'
note "  curl -i -X POST $MCP_URL"
note "    → $(status "$MCP_URL" POST), WWW-Authenticate: $(challenge)"
note "  curl $API/.well-known/oauth-protected-resource/mcp"
note "    → resource $(metadata | jq -r .resource), authorization server $ISSUER"
note "  curl $ISSUER/.well-known/oauth-authorization-server"
note "    → PKCE $(curl -fsS --max-time 10 "$ISSUER/.well-known/oauth-authorization-server" | jq -c .code_challenge_methods_supported), public clients $(curl -fsS --max-time 10 "$ISSUER/.well-known/oauth-authorization-server" | jq -r '.client_id_metadata_document_supported // false')"
printf '\n'
expected_challenge="resource_metadata=\"$API/.well-known/oauth-protected-resource/mcp\""
if [[ "$(status "$MCP_URL" POST)" == 401 && "$(challenge)" == *"$expected_challenge"* ]] \
  && mcp_live && clerk_ready; then
  ok "Every hop answers as it should"
else
  warn "A hop isn't right yet (expected 401 with a challenge, and true for public clients)."
  SKIPPED+=("A curl check above didn't pass: re-run this wizard to repeat it")
fi
printf '\n'; pause

# ── 6. Claude Code ────────────────────────────────────────────────────────
stage "Claude Code"
say "Adds duckbill for every project (user scope) and signs in through Clerk."
if command -v claude >/dev/null 2>&1; then
  existing=$(claude mcp get duckbill 2>/dev/null || true)
  elsewhere=""
  if [[ "$existing" == *"$MCP_URL"* ]]; then
    ok "Claude Code already has duckbill at $MCP_URL"
  elif [[ -n "$existing" ]]; then
    elsewhere=1
    warn "Claude Code's duckbill points somewhere else (perhaps the local demo):"
    note "$(grep -iE 'url|scope' <<<"$existing" || true)"
    SKIPPED+=("Claude Code: remove the other duckbill (claude mcp remove duckbill), then re-run")
  elif confirm "Run: claude mcp add --transport http --scope user duckbill $MCP_URL ?"; then
    claude mcp add --transport http --scope user duckbill "$MCP_URL" \
      || warn "Claude Code didn't add it; run that command yourself."
  fi
  if [[ -n "$elsewhere" ]]; then
    :
  elif confirm "Sign in now (claude mcp login duckbill)? It opens Clerk in your browser."; then
    step "Continue with Google, the account you use for the dashboard."
    claude mcp login duckbill || warn "Sign-in didn't finish. In Claude Code, run /mcp and pick duckbill."
  else
    note "Later: run /mcp in Claude Code and pick duckbill to sign in."
  fi
  printf '\n'; tools_check "Claude Code"
else
  note "The claude CLI isn't installed here. On a machine that has it:"
  note "  claude mcp add --transport http --scope user duckbill $MCP_URL"
  note "  claude mcp login duckbill"
  SKIPPED+=("Claude Code: add duckbill with the two commands above")
fi
printf '\n'; pause

# ── 7. claude.ai ──────────────────────────────────────────────────────────
stage "claude.ai: add the connector"
say "Connectors follow your Claude account, so this covers the desktop and phone apps too."
open_url "https://claude.ai/customize/connectors"
step "Customize → Connectors → + Add → Add custom connector."
step "Name: duckbill. URL, then Continue:"
note "      $MCP_URL"
copy "$MCP_URL" && note "      (on your clipboard)"
step "Review the authentication settings Claude detected, then Continue."
step "Authentication: Sign in now. OAuth client: Use Claude's published identity. Then Add."
step "Clerk's sign-in opens: continue with Google, the account you use for the dashboard."
say  "  Clerk's development banner there is expected. Allow access when asked."
printf '\n'; pause "Press Enter once duckbill shows as connected."
tools_check "claude.ai"
printf '\n'; pause

# ── 8. Grok Bot ───────────────────────────────────────────────────────────
stage "Grok Bot: add the connector"
say "Grok Bot's connector dialog isn't documented. Try these in order and stop at the"
say "first that answers from duckbill."
step "1. URL only: $MCP_URL"
say  "   If it opens Clerk's sign-in, continue with Google, the account you use for the dashboard."
step "2. If it asks for an OAuth client ID: Clerk → duckbill → Development → OAuth applications →"
say  "   Add OAuth application, named Grok Bot, with Grok's callback URL as the redirect URI"
say  "   (Grok's dialog or its error message shows it) and the profile scope. If Grok has no field"
say  "   for a client secret, make it a public client. Paste its Client ID into Grok."
copy "$MCP_URL" && note "The URL is on your clipboard."
if confirm "Has Grok Bot connected?"; then
  tools_check "Grok Bot"
else
  open_url "https://dashboard.clerk.com/~/oauth-applications"
  SKIPPED+=("Grok Bot: connect it with one of the two options, then ask it for your balances")
fi
printf '\n'; pause "Press Enter to finish."

finish
note "Every tool is read-only, and an agent only gets a token when you sign in for it."
note "To cut one off, remove its connector; a token it already holds works until it expires."
printf '\n'
}

run_wizard "$@"; exit
